    const createdAt = new Date(createdAtMs).toISOString();
    const text = item.story_text || item.title || '';
    const urls = item.url ? [item.url] : [];
    return {
      json: {
        platform: 'hackernews',
        external_id: String(item.objectID),
        text_content: text,
        language: 'en',
        created_at: createdAt,
        author_username: item.author || 'anonymous',
        author_id: item.author || 'unknown',
        author_verified: false,
        author_followers_count: item.points || 0,
        author_description: null,
        likes_count: item.points || 0,
        shares_count: 0,
        replies_count: item.num_comments || 0,
        views_count: 0,
        urls: urls,
        hashtags: [],
        mentions: [],
        has_media: false,
        is_reply: false,
        is_quote: false,
        reply_to_id: null,
        conversation_id: null,
        raw_data: item
      }
    };
  });
} catch (error) {
