// =============================================
// Aggregate Alerts
// Collects ALL high/critical items from this batch
// into a single consolidated item for summary alerting.
// This ensures N alerts = 1 email + 1 Slack message.
// =============================================

const items = $input.all();

if (!items || items.length === 0) {
  return [];
}

const alerts = items.map(item => {
  const d = item.json;
  const threat = d.threat || {};
  const fallbackUrls = {
    'hackernews': 'https://news.ycombinator.com/item?id=' + (d.external_id || ''),
    'exploit-db': 'https://www.exploit-db.com/',
    'github': 'https://github.com/search?q=security&type=issues'
  };
  const sourceUrl = (d.urls && d.urls.length > 0)
    ? d.urls[0]
    : (fallbackUrls[d.platform] || 'https://news.ycombinator.com/');
  return {
    detection_id: d.detection_id || null,
    mention_id: d.mention_id || null,
    text_content: d.text_content || '',
    platform: d.platform || 'unknown',
    author: d.author_username || 'unknown',
    criticality_level: d.criticality_level || threat.criticality_level || 'high',
    threat_type: threat.threat_type || 'general',
    confidence_score: threat.confidence_score || 0,
    source_url: sourceUrl,
    detected_at: d.created_at || new Date().toISOString()
  };
});

// Determine highest severity across all alerts
const hasCritical = alerts.some(a => a.criticality_level === 'critical');
const highestSeverity = hasCritical ? 'critical' : 'high';

return [{
  json: {
    alert_count: alerts.length,
    alerts: alerts,
    execution_timestamp: new Date().toISOString(),
    highest_severity: highestSeverity
  }
}];

// =============================================
// Build Alert Content
// Receives ONE consolidated item from Aggregate Alerts
// with an alerts[] array. Produces a single summary email,
// a Slack Block Kit message, and a plain-text log message.
