// ── Helpers ────────────────────────────────────────────────────────────────
const escHtml = (v) => String(v ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const fmtTimestamp = (iso) => {
  try { return new Date(iso).toLocaleString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires' }); }
  catch (e) { return iso; }
};

const fmtConfidence = (score) => ((score || 0) * 100).toFixed(1) + '%';

const truncate = (str, max) => {
  const s = String(str || '');
  return s.length > max ? s.slice(0, max) + '…' : s;
};

// ── Email subject ───────────────────────────────────────────────────────────
let subjectParts = [];
if (criticalCount > 0) subjectParts.push(criticalCount + ' critical');
if (highCount > 0) subjectParts.push(highCount + ' high');
const email_subject = '[NSG] Scan Report — ' + alertCount + ' alert' + (alertCount !== 1 ? 's' : '') + ' detected (' + subjectParts.join(', ') + ')';

