// =============================================
// Prep Alert Insert
// Builds deterministic SQL for alerts insert.
// Avoid queryReplacement with external alert text.
// =============================================

const items = $input.all();
const result = [];

const sqlString = (val) => String(val ?? '')
  .replace(/�/g, '')
  .replace(/'/g, "''");

for (const item of items) {
  const d = item.json;

  // Validate required FK before building SQL.
  const detectionId = Number(d.detection_id);
  if (!Number.isInteger(detectionId) || detectionId <= 0) {
    console.warn('Prep Alert Insert: skipping alert with invalid detection_id=' + d.detection_id);
    continue;
  }

  // Map detection criticality to alert severity.
  // The IF node sends Enrich After Threat items directly to this node,
  // so d.alert_severity is usually absent. Falling back to 'info'
  // incorrectly logs high/critical detections as informational alerts.
  const validSeverities = ['info', 'warning', 'high', 'critical'];
  const detectedLevel = d.alert_severity || d.criticality_level || (d.threat || {}).criticality_level;
  const severity = validSeverities.includes(detectedLevel) ? detectedLevel : 'warning';
  const title = 'Amenaza ' + severity + ' detectada';
  const message = d.alert_message || '';

  const query = [
    'INSERT INTO alerts (',
    '  detection_id, alert_title, alert_message, alert_severity,',
    '  channels_sent, slack_channel, sent_at, delivery_status',
    ') VALUES (',
    '  ' + detectionId + ',',
    "  '" + sqlString(title) + "',",
    "  '" + sqlString(message) + "',",
    "  '" + severity + "',",
    "  ARRAY['slack', 'email'],",
    "  '#security-alerts',",
    '  NOW(),',
    "  'sent'",
    ')',
    'RETURNING alert_id;'
  ].join(String.fromCharCode(10));

  result.push({
    json: {
      p_detection_id: detectionId,
      p_alert_title: title,
      p_alert_message: message,
      p_alert_severity: severity,
      query,

      // Carry forward for Log Execution
      _original: d
    }
  });
}

return result;

// =============================================
// Summarize Skipped Items
// Counts items that did NOT trigger an alert
// (low/medium criticality) and summarizes by level.
// =============================================

const items = $input.all();
const counts = { low: 0, medium: 0 };

for (const item of items) {
  const level = item.json.criticality_level || 'low';
  counts[level] = (counts[level] || 0) + 1;
}

const summary = Object.entries(counts)
  .filter(([_, c]) => c > 0)
  .map(([level, count]) => count + ' ' + level)
  .join(', ');

console.log('Items below alert threshold: ' + (summary || 'none') + ' (total: ' + items.length + ')');

return [{ json: { skipped_total: items.length, skipped_by_level: counts, summary: summary || 'none' } }];

// =============================================
// Prep Log Execution
// Aggregates pipeline counters from canonical upstream nodes.
// Robustness rule: execution logging must NOT depend on items
// surviving Filter Already Processed.
//
// Triggering rules:
// - Enrich After Threat triggers the normal log path when there are new items.
// - Check Existing IDs triggers the all-existing path when every deduped item
//   was skipped before analysis/storage.
// - Mixed/new executions are deferred from the Check Existing IDs trigger to
//   avoid duplicate execution_logs rows and to wait for downstream counters.
// =============================================

const getNodeItems = (nodeName) => {
  try {
    return $(nodeName).all() || [];
  } catch (e) {
    console.warn('Prep Log Execution: node unavailable: ' + nodeName + ' — ' + e.message);
    return [];
  }
};

const safeJson = (item) => (item && item.json) ? item.json : {};
const hasError = (item) => {
  const j = safeJson(item);
  return !!(j.error || j.errorMessage);
};
const countSuccessful = (items, idField) =>
  items.filter(item => !hasError(item) && safeJson(item)[idField]).length;
const identityKey = (item) => {
  const j = safeJson(item);
  const platform = String(j.platform || '').trim().toLowerCase();
  const externalId = String(j.external_id || '').trim();
  return platform && externalId ? platform + '::' + externalId : null;
};

const currentInput = $input.all();
const deduplicatedItems = getNodeItems('Deduplicate');
const existingResults = getNodeItems('Check Existing IDs');
const mentionResults = getNodeItems('Insert Social Mention');
const sentimentResults = getNodeItems('Insert Sentiment Analysis');
const threatResults = getNodeItems('Insert Threat Detection');
const enrichedThreatItems = getNodeItems('Enrich After Threat');
const alertResults = getNodeItems('Log Alert in DB');

const mentionsCollected = deduplicatedItems.length;

const existingKeys = new Set();
for (const row of existingResults) {
  if (!hasError(row)) {
    const key = identityKey(row);
    if (key) existingKeys.add(key);
  }
}

let skippedExisting = 0;
for (const item of deduplicatedItems) {
  const key = identityKey(item);
  if (key && existingKeys.has(key)) skippedExisting++;
}

const newItemsToProcess = Math.max(0, mentionsCollected - skippedExisting);
const inputLooksLikeProcessedThreat = currentInput.some(item => !!safeJson(item).detection_id);
const invokedFromExistingCheckPath = !inputLooksLikeProcessedThreat;

// The Check Existing IDs branch exists only to cover the all-existing case.
// If there are new items, the Enrich After Threat branch will log later with
// complete downstream counters. Returning [] here prevents duplicate rows.
if (invokedFromExistingCheckPath && newItemsToProcess > 0) {
  console.log('Prep Log Execution: deferring log until new item processing completes (' + newItemsToProcess + ' new, ' + skippedExisting + ' existing skipped)');
  return [];
}

const existingCheckErrors = existingResults.filter(i => hasError(i)).length;
const mentionErrors = mentionResults.filter(i => hasError(i) || !safeJson(i).mention_id).length;
const sentimentErrors = sentimentResults.filter(i => hasError(i) || !safeJson(i).sentiment_id).length;
const threatErrors = threatResults.filter(i => hasError(i) || !safeJson(i).detection_id).length;
const totalErrors = existingCheckErrors + mentionErrors + sentimentErrors + threatErrors;

const mentionsProcessed = countSuccessful(mentionResults, 'mention_id');
const sentimentInserted = countSuccessful(sentimentResults, 'sentiment_id');
const detectionsGenerated = countSuccessful(threatResults, 'detection_id');

const levels = { low: 0, medium: 0, high: 0, critical: 0, unknown: 0 };
for (const item of enrichedThreatItems) {
  const j = safeJson(item);
  const rawLevel = String(j.criticality_level || (j.threat || {}).criticality_level || 'unknown').toLowerCase();
  const level = Object.prototype.hasOwnProperty.call(levels, rawLevel) ? rawLevel : 'unknown';
  levels[level]++;
}

const skippedBelowAlertTotal = levels.low + levels.medium + levels.unknown;
const skippedTotal = skippedExisting + skippedBelowAlertTotal;
const alertCandidates = levels.high + levels.critical;
const skippedParts = [];
if (skippedExisting > 0) skippedParts.push(skippedExisting + ' existing');
for (const [level, count] of Object.entries({ low: levels.low, medium: levels.medium, unknown: levels.unknown })) {
  if (count > 0) skippedParts.push(count + ' ' + level);
}
const skippedSummary = skippedParts.join(', ');

// If alert logging already ran in this execution, prefer actual successful DB inserts.
// Otherwise fall back to deterministic high/critical candidates so the execution log
// remains independent from IF branch timing and n8n branch execution quirks.
const successfulAlertInserts = alertResults.filter(item => !hasError(item) && safeJson(item).alert_id).length;
const alertsGenerated = successfulAlertInserts > 0 ? successfulAlertInserts : alertCandidates;

const status = totalErrors > 0 ? (mentionsProcessed === 0 && skippedExisting === 0 ? 'error' : 'partial_success') : 'success';

console.log(
  'Execution summary — collected: ' + mentionsCollected +
  ', existing_skipped: ' + skippedExisting +
  ', mentions: ' + mentionsProcessed +
  ', sentiments: ' + sentimentInserted +
  ', detections: ' + detectionsGenerated +
  ', alert_candidates: ' + alertCandidates +
  ', skipped_total: ' + skippedTotal + (skippedSummary ? ' (' + skippedSummary + ')' : '')
);

if (totalErrors > 0) {
  console.warn('Execution errors — existing_check: ' + existingCheckErrors + ', mention_insert: ' + mentionErrors + ', sentiment_insert: ' + sentimentErrors + ', threat_insert: ' + threatErrors);
}

return [{
  json: {
    p_workflow_name: 'OSINT Monitor Multi-Platform',
    p_execution_id: $execution.id,
    p_status: status,
    p_mentions_collected: mentionsCollected,
    p_mentions_processed: mentionsProcessed,
    p_detections_generated: detectionsGenerated,
    p_alerts_generated: alertsGenerated,
    skipped_total: skippedTotal,
    skipped_existing: skippedExisting,
    skipped_below_alert_total: skippedBelowAlertTotal,
    skipped_by_level: levels,
    skipped_summary: skippedSummary || 'none',
    new_items_to_process: newItemsToProcess,
    sentiment_inserted: sentimentInserted
  }
}];
